mkdir -p src/orders && cat > src/orders/data.ts <<'EOF'
export type OrderStatus = 'new' | 'processing' | 'shipped' | 'delivered' | 'cancelled';

export interface Order {
  id: string;
  number: string;
  customer: string;
  status: OrderStatus;
  total: number;
  itemsCount: number;
  city: string;
  createdAt: string;
}

export interface OrderGroup {
  id: string;
  status: OrderStatus;
  items: Order[];
}

export type OrderRow = Order | OrderGroup;

export const isOrderGroup = (row: OrderRow): row is OrderGroup => 'items' in row;

export const STATUS_ORDER: OrderStatus[] = ['new', 'processing', 'shipped', 'delivered', 'cancelled'];

export const STATUS_TITLES: Record<OrderStatus, string> = {
  new: 'Новый',
  processing: 'В обработке',
  shipped: 'Отправлен',
  delivered: 'Доставлен',
  cancelled: 'Отменён',
};

const CUSTOMERS = [
  'Иванов Пётр',
  'Смирнова Анна',
  'Кузнецов Олег',
  'Попова Мария',
  'Васильев Игорь',
  'Соколова Елена',
  'Михайлов Денис',
  'Новикова Ольга',
  'Фёдоров Андрей',
  'Морозова Ксения',
  'Волков Сергей',
  'Алексеева Дарья',
];

const CITIES = ['Москва', 'Санкт-Петербург', 'Казань', 'Новосибирск', 'Екатеринбург', 'Сочи'];

// Deterministic pseudo-random generator so the demo data is stable between renders.
function createRng(seed: number) {
  let state = seed;
  return () => {
    state = (state * 1664525 + 1013904223) % 4294967296;
    return state / 4294967296;
  };
}

export function generateOrders(count: number): Order[] {
  const rng = createRng(42);
  const pick = <T,>(list: T[]) => list[Math.floor(rng() * list.length)];
  const start = new Date('2026-10-01T09:00:00Z').getTime();

  return Array.from({length: count}, (_, index) => {
    const number = 10240 + index;
    const createdAt = new Date(start + Math.floor(rng() * 35 * 24 * 60 * 60 * 1000));
    return {
      id: `order-${number}`,
      number: `#${number}`,
      customer: pick(CUSTOMERS),
      status: pick(STATUS_ORDER),
      total: Math.round((500 + rng() * 49500) / 10) * 10,
      itemsCount: 1 + Math.floor(rng() * 9),
      city: pick(CITIES),
      createdAt: createdAt.toISOString(),
    };
  });
}

export function groupOrdersByStatus(orders: Order[]): OrderGroup[] {
  return STATUS_ORDER.map((status) => ({
    id: `group-${status}`,
    status,
    items: orders.filter((order) => order.status === status),
  })).filter((group) => group.items.length > 0);
}

export const currencyFormatter = new Intl.NumberFormat('ru-RU', {
  style: 'currency',
  currency: 'RUB',
  maximumFractionDigits: 0,
});

export const dateFormatter = new Intl.DateTimeFormat('ru-RU', {
  day: '2-digit',
  month: '2-digit',
  year: 'numeric',
  hour: '2-digit',
  minute: '2-digit',
});
EOF
cat > src/orders/OrdersTable.tsx <<'EOF'
import React from 'react';
import {
  ColumnReorderingProvider,
  Table,
  selectionColumn,
  useRowSelectionFixedHandler,
  useTable,
} from '@gravity-ui/table';
import type {ColumnReorderingProviderProps} from '@gravity-ui/table';
import type {ColumnDef, ExpandedState, Row, RowSelectionState, SortingState} from '@gravity-ui/table/tanstack';
import {Button, Flex, Label, Switch, Text} from '@gravity-ui/uikit';

import {
  STATUS_TITLES,
  currencyFormatter,
  dateFormatter,
  generateOrders,
  groupOrdersByStatus,
  isOrderGroup,
} from './data';
import type {Order, OrderRow, OrderStatus} from './data';

const STATUS_LABEL_THEME: Record<OrderStatus, 'info' | 'warning' | 'utility' | 'success' | 'danger'> = {
  new: 'info',
  processing: 'warning',
  shipped: 'utility',
  delivered: 'success',
  cancelled: 'danger',
};

const orderValue = <T,>(row: OrderRow, pick: (order: Order) => T): T | undefined =>
  isOrderGroup(row) ? undefined : pick(row);

const columns: ColumnDef<OrderRow>[] = [
  {
    ...(selectionColumn as ColumnDef<OrderRow>),
    enableColumnReordering: false,
  },
  {
    id: 'number',
    accessorFn: (row) => orderValue(row, (order) => order.number),
    header: 'Номер',
    size: 110,
    enableSorting: true,
  },
  {
    id: 'customer',
    accessorFn: (row) => orderValue(row, (order) => order.customer),
    header: 'Клиент',
    size: 220,
    enableSorting: true,
  },
  {
    id: 'status',
    accessorFn: (row) => row.status,
    header: 'Статус',
    size: 150,
    enableSorting: true,
    cell: ({row}) =>
      isOrderGroup(row.original) ? null : (
        <Label theme={STATUS_LABEL_THEME[row.original.status]} size="xs">
          {STATUS_TITLES[row.original.status]}
        </Label>
      ),
  },
  {
    id: 'total',
    accessorFn: (row) => orderValue(row, (order) => order.total),
    header: 'Сумма',
    size: 140,
    enableSorting: true,
    cell: ({row}) =>
      isOrderGroup(row.original) ? null : (
        <Text variant="body-1" style={{display: 'block', textAlign: 'right', fontVariantNumeric: 'tabular-nums'}}>
          {currencyFormatter.format(row.original.total)}
        </Text>
      ),
  },
  {
    id: 'itemsCount',
    accessorFn: (row) => orderValue(row, (order) => order.itemsCount),
    header: 'Позиций',
    size: 110,
    enableSorting: true,
    cell: ({row}) =>
      isOrderGroup(row.original) ? null : (
        <Text variant="body-1" style={{display: 'block', textAlign: 'right', fontVariantNumeric: 'tabular-nums'}}>
          {row.original.itemsCount}
        </Text>
      ),
  },
  {
    id: 'city',
    accessorFn: (row) => orderValue(row, (order) => order.city),
    header: 'Город',
    size: 170,
    enableSorting: true,
  },
  {
    id: 'createdAt',
    accessorFn: (row) => orderValue(row, (order) => order.createdAt),
    header: 'Создан',
    size: 160,
    enableSorting: true,
    cell: ({row}) =>
      isOrderGroup(row.original) ? null : dateFormatter.format(new Date(row.original.createdAt)),
  },
];

const ORDERS: Order[] = generateOrders(120);
const GROUPED_ORDERS = groupOrdersByStatus(ORDERS);

const getRowId = (row: OrderRow) => row.id;
const getSubRows = (row: OrderRow) => (isOrderGroup(row) ? row.items : undefined);
const getGroupTitle = (row: Row<OrderRow>) => {
  const group = row.original;
  if (!isOrderGroup(group)) {
    return null;
  }
  return (
    <Flex gap={2} alignItems="center">
      <Text variant="subheader-1">{STATUS_TITLES[group.status]}</Text>
      <Text variant="body-1" color="secondary">
        {group.items.length}
      </Text>
    </Flex>
  );
};

export function OrdersTable() {
  const [groupByStatus, setGroupByStatus] = React.useState(true);
  const [rowSelection, setRowSelection] = React.useState<RowSelectionState>({});
  const [expanded, setExpanded] = React.useState<ExpandedState>(true);
  const [sorting, setSorting] = React.useState<SortingState>([]);
  const [columnOrder, setColumnOrder] = React.useState<string[]>([]);

  const data = React.useMemo<OrderRow[]>(() => (groupByStatus ? GROUPED_ORDERS : ORDERS), [groupByStatus]);

  // Keeps parent (group) checkboxes consistent with their children when rows are nested.
  const handleRowSelectionChange = useRowSelectionFixedHandler<OrderRow>({
    rowSelection,
    setRowSelection,
    tableData: data,
    getSubRows,
    getRowId,
  });

  const table = useTable({
    columns,
    data,
    getRowId,
    getSubRows,
    enableRowSelection: true,
    enableMultiRowSelection: true,
    onRowSelectionChange: handleRowSelectionChange,
    enableExpanding: groupByStatus,
    onExpandedChange: setExpanded,
    enableSorting: true,
    onSortingChange: setSorting,
    onColumnOrderChange: setColumnOrder,
    state: {
      rowSelection,
      expanded: groupByStatus ? expanded : {},
      sorting,
      columnOrder,
    },
  });

  const handleColumnReorder = React.useCallback<
    NonNullable<ColumnReorderingProviderProps<OrderRow>['onReorder']>
  >(({columnOrder: nextOrder}) => {
    setColumnOrder(nextOrder);
  }, []);

  const selectedOrdersCount = React.useMemo(
    () => Object.entries(rowSelection).filter(([id, selected]) => selected && id.startsWith('order-')).length,
    [rowSelection],
  );

  return (
    <Flex direction="column" gap={3} style={{flex: 1, minHeight: 0}}>
      <Flex alignItems="center" gap={4} wrap="wrap" style={{flexShrink: 0}}>
        <Switch
          size="m"
          checked={groupByStatus}
          onUpdate={setGroupByStatus}
          content="Группировать по статусу"
        />
        <Text variant="body-1" color="secondary">
          Выбрано заказов: {selectedOrdersCount}
